// The physics library through its C interface: casts of lines and ellipsoids against what is worked out by hand, the number of the
// triangle that is hit, moving and removing bodies, and a batch on all threads against the same casts one at a time.

#include "blitzphysics.h"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>

static int failures = 0;

#define CHECK(condition)                                                              \
	do {                                                                              \
		if (!(condition)) {                                                           \
			std::printf("FAILED %s:%d: %s\n", __FILE__, __LINE__, #condition);        \
			failures++;                                                               \
		}                                                                             \
	} while (0)

static bool near(float a, float b, float epsilon = 1e-3f) { return std::fabs(a - b) <= epsilon; }

static const float zero[3]  = { 0, 0, 0 };
static const float turn0[4] = { 0, 0, 0, 1 };
static const float one[3]   = { 1, 1, 1 };

// A floor of two triangles at y = 0, 20 by 20 around the origin. Triangle 0 is the one with x + z < 0 side... which is which is
// found out by the test, not assumed.
static bp_mesh* make_floor(float y)
{
	const float    positions[] = { -10, y, -10, 10, y, -10, 10, y, 10, -10, y, 10 };
	const uint32_t indices[]   = { 0, 2, 1, 0, 3, 2 };
	return bp_mesh_create(positions, 4, indices, 2);
}

static void test_line()
{
	bp_world* world = bp_world_create(1);
	bp_mesh*  floor = make_floor(0);
	CHECK(world && floor);
	bp_body body = bp_body_add_mesh(world, floor, zero, turn0, one, 77, 0);
	CHECK(body != 0);

	bp_cast cast = { { 2, 5, 3 }, { 0, -10, 0 }, { 0, 0, 0 } };
	bp_hit  hit;
	bp_cast_closest(world, &cast, &hit);
	CHECK(hit.hit == 1);
	CHECK(near(hit.fraction, 0.5f));
	CHECK(near(hit.point[0], 2) && near(hit.point[1], 0) && near(hit.point[2], 3));
	CHECK(near(std::fabs(hit.normal[1]), 1));
	CHECK(hit.user == 77);
	CHECK(hit.body == body);
	CHECK(hit.triangle < 2);
	uint32_t first = hit.triangle;

	// The other half of the floor is the other triangle.
	bp_cast other = { { -2, 5, -3 }, { 0, -10, 0 }, { 0, 0, 0 } };
	bp_cast_closest(world, &other, &hit);
	CHECK(hit.hit == 1 && hit.triangle < 2 && hit.triangle != first);

	// Too short, and beside.
	bp_cast short_cast = { { 2, 5, 3 }, { 0, -2, 0 }, { 0, 0, 0 } };
	bp_cast_closest(world, &short_cast, &hit);
	CHECK(hit.hit == 0);
	bp_cast beside = { { 20, 5, 3 }, { 0, -10, 0 }, { 0, 0, 0 } };
	bp_cast_closest(world, &beside, &hit);
	CHECK(hit.hit == 0);

	// From below: triangles are hit from both sides.
	bp_cast below = { { 2, -5, 3 }, { 0, 10, 0 }, { 0, 0, 0 } };
	bp_cast_closest(world, &below, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.5f));

	// Bodies can be left out: by their user value, or by the bits of it.
	uint64_t ignored[1] = { 77 };
	bp_cast  ignoring   = cast;
	ignoring.ignore       = ignored;
	ignoring.ignore_count = 1;
	bp_cast_closest(world, &ignoring, &hit);
	CHECK(hit.hit == 0);
	bp_cast masked = cast;
	masked.user_mask  = 0xff;
	masked.user_value = 77 & 0xff;
	bp_cast_closest(world, &masked, &hit);
	CHECK(hit.hit == 1 && hit.user == 77);
	masked.user_value = 1;
	bp_cast_closest(world, &masked, &hit);
	CHECK(hit.hit == 0);

	bp_body_remove(world, body);
	bp_cast_closest(world, &cast, &hit);
	CHECK(hit.hit == 0);
	bp_mesh_destroy(floor);
	bp_world_destroy(world);
}

static void test_ellipsoid()
{
	bp_world* world = bp_world_create(1);
	bp_mesh*  floor = make_floor(0);
	bp_body   body  = bp_body_add_mesh(world, floor, zero, turn0, one, 1, 0);
	CHECK(body != 0);

	// A sphere of radius 0.5 falling: it touches when its center is 0.5 above the floor, 4.5 of 10 down from 5.
	bp_cast sphere = { { 2, 5, 3 }, { 0, -10, 0 }, { 0.5f, 0.5f, 0.5f } };
	bp_hit  hit;
	bp_cast_closest(world, &sphere, &hit);
	CHECK(hit.hit == 1);
	CHECK(near(hit.fraction, 0.45f, 2e-3f));
	CHECK(near(hit.point[1], 0, 2e-3f));
	CHECK(hit.normal[1] > 0.99f);

	// The same with a taller ellipsoid touches earlier, a flat one later.
	bp_cast tall = { { 2, 5, 3 }, { 0, -10, 0 }, { 0.5f, 2.0f, 0.5f } };
	bp_cast_closest(world, &tall, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.3f, 2e-3f));
	bp_cast flat = { { 2, 5, 3 }, { 0, -10, 0 }, { 2.0f, 0.25f, 2.0f } };
	bp_cast_closest(world, &flat, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.475f, 2e-3f));

	bp_mesh_destroy(floor);
	bp_world_destroy(world);
}

static void test_bodies()
{
	bp_world* world = bp_world_create(1);
	const float half[3] = { 1, 1, 1 };
	const float at[3]   = { 0, 0, 5 };
	bp_body     box     = bp_body_add_box(world, half, at, turn0, one, 5, 1);
	CHECK(box != 0);
	bp_hit  hit;
	bp_cast line = { { 0, 0, 0 }, { 0, 0, 10 }, { 0, 0, 0 } };
	bp_cast_closest(world, &line, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.4f) && hit.user == 5 && hit.triangle == 0);

	// Moved, scaled.
	const float moved[3] = { 0, 0, 8 };
	bp_body_set_transform(world, box, moved, turn0, one);
	bp_cast_closest(world, &line, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.7f));
	const float twice[3] = { 2, 2, 2 };
	bp_body_set_transform(world, box, moved, turn0, twice);
	bp_cast_closest(world, &line, &hit);
	CHECK(hit.hit == 1 && near(hit.fraction, 0.6f));

	// An ellipsoid is hit where its surface is.
	const float radii[3] = { 1, 1, 3 };
	const float far_at[3] = { 0, 0, 30 };
	bp_body     ball      = bp_body_add_ellipsoid(world, radii, far_at, turn0, one, 6, 0);
	CHECK(ball != 0);
	bp_cast far_line = { { 0, 0, 20 }, { 0, 0, 20 }, { 0, 0, 0 } };
	bp_cast_closest(world, &far_line, &hit);
	CHECK(hit.hit == 1 && hit.user == 6 && near(hit.fraction, 0.35f, 5e-3f));

	// Nothing that is not valid becomes a body.
	CHECK(bp_mesh_create(nullptr, 0, nullptr, 0) == nullptr);
	const float    positions[] = { 0, 0, 0, 1, 0, 0, 0, 1, 0 };
	const uint32_t bad[]       = { 0, 1, 5 };
	CHECK(bp_mesh_create(positions, 3, bad, 1) == nullptr);
	CHECK(bp_body_add_mesh(world, nullptr, zero, turn0, one, 0, 0) == 0);
	bp_world_destroy(world);
}

// 3000 casts into a lumpy mesh, one at a time and as a batch on 4 threads: the same answers, in the same places.
static void test_batch()
{
	const int      n = 40;
	std::vector<float>    positions;
	std::vector<uint32_t> indices;
	for (int z = 0; z <= n; z++) {
		for (int x = 0; x <= n; x++) {
			positions.push_back(float(x));
			positions.push_back(0.4f * std::sin(x * 0.7f) * std::cos(z * 0.5f));
			positions.push_back(float(z));
		}
	}
	for (int z = 0; z < n; z++) {
		for (int x = 0; x < n; x++) {
			uint32_t a = uint32_t(z * (n + 1) + x), b = a + 1, c = a + uint32_t(n + 1), d = c + 1;
			indices.insert(indices.end(), { a, c, b, b, c, d });
		}
	}
	bp_mesh* mesh = bp_mesh_create(positions.data(), uint32_t(positions.size() / 3), indices.data(), uint32_t(indices.size() / 3));
	CHECK(mesh != nullptr);
	bp_world* world = bp_world_create(4);
	bp_body   body  = bp_body_add_mesh(world, mesh, zero, turn0, one, 9, 0);
	CHECK(body != 0);

	std::vector<bp_cast> casts;
	unsigned             seed = 12345;
	auto                 random = [&]() {
        seed = seed * 1664525u + 1013904223u;
        return float(seed >> 8) / 16777216.0f;
	};
	for (int i = 0; i < 3000; i++) {
		bp_cast cast = { { random() * n, 3.0f, random() * n }, { 0, -5.0f, 0 }, { 0, 0, 0 } };
		if (i % 2) {
			cast.radii[0] = 0.5f;
			cast.radii[1] = 0.8f;
			cast.radii[2] = 0.5f;
		}
		casts.push_back(cast);
	}
	std::vector<bp_hit> single(casts.size()), batch(casts.size());
	for (size_t i = 0; i < casts.size(); i++) {
		bp_cast_closest(world, &casts[i], &single[i]);
	}
	bp_cast_closest_batch(world, casts.data(), batch.data(), uint32_t(casts.size()));
	int hits = 0, different = 0;
	for (size_t i = 0; i < casts.size(); i++) {
		hits += single[i].hit;
		if (single[i].hit != batch[i].hit || single[i].triangle != batch[i].triangle || single[i].fraction != batch[i].fraction) {
			different++;
		}
	}
	CHECK(hits > 2900);
	CHECK(different == 0);
	std::printf("batch: %d hits of %zu, %d different\n", hits, casts.size(), different);

	bp_mesh_destroy(mesh);
	bp_world_destroy(world);
}

int main()
{
	CHECK(bp_version() == BP_VERSION);
	test_line();
	test_ellipsoid();
	test_bodies();
	test_batch();
	if (failures) {
		std::printf("%d checks failed\n", failures);
		return 1;
	}
	std::printf("physics library: all checks passed\n");
	return 0;
}
